// Some portions generated by Claude
import assert from 'node:assert/strict';
import test from 'node:test';
import {computeGraphLayout} from '../../../main/frontend/graph-explorer/graph-layout-engine.ts';
import {computeEdgePorts, edgeGeometry, edgePortKey, graphNodeSize, optimizeEdgeBends, quadraticPoint} from '../../../main/frontend/graph-explorer/graph-geometry.ts';
import {improveLayoutReadability} from '../../../main/frontend/graph-explorer/graph-layout-readability.ts';
import {layoutMetrics} from './support/benchmark-layout.mjs';
import {indexedIntersections} from './fixtures/layout-measurements.mjs';

const node = (id, x, y, label = id) => ({id, label, kind: 'iri', x, y});
const edge = (source, target, id = `${source}-${target}`) => ({id, source, target, predicate: 'urn:p', label: 'related to'});
function sampledObstructions(nodes, edges, bends) {
  const byId = new Map(nodes.map(n => [n.id, n])), ports = computeEdgePorts(nodes, edges);
  let count = 0;
  for (const e of edges) {
    const curve = edgeGeometry(byId.get(e.source), byId.get(e.target), bends.get(e.id) ?? 0,
      ports.get(edgePortKey(e.id, e.source)), ports.get(edgePortKey(e.id, e.target)));
    for (const n of nodes) {
      if (n.id === e.source || n.id === e.target) continue;
      const size = graphNodeSize(n);
      for (let i = 0; i <= 4000; i++) {
        const p = quadraticPoint(curve.start, curve.control, curve.end, i / 4000);
        if (Math.abs(p.x - n.x) < size.width / 2 + 3 && Math.abs(p.y - n.y) < size.height / 2 + 3) {count++; break;}
      }
    }
  }
  return count;
}

for (const y of [110, 300, 1000]) test(`routing avoids a card at y=${y}, including gaps between old curve samples`, () => {
  const nodes = [node('a', 0, 0), node('z', 0, 2000), node('obstacle', 0, y, 'A wide unrelated card')];
  const edges = [edge('a', 'z')], before = structuredClone(nodes);
  const bends = optimizeEdgeBends(nodes, edges, 1);
  assert.equal(sampledObstructions(nodes, edges, bends), 0);
  assert.deepEqual(nodes, before, 'routing must not move cards');
  assert.deepEqual(bends, optimizeEdgeBends(nodes, edges, 1));
});

test('refine leaves an already-clear manually arranged map exactly where it is', async () => {
  const graph = {revision: 1, nodes: [node('a', -250, 0), node('b', 250, 0), node('c', 250, 300)], edges: [edge('a', 'b'), edge('b', 'c')]};
  const result = await computeGraphLayout(graph, {refine: true});
  assert.deepEqual(result.positions, new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}])));
});

test('refine repairs a blocked neighborhood without moving pinned context', async () => {
  const graph = {revision: 1, nodes: [node('a', -400, 0), node('z', 400, 0), node('obstacle', 0, 0), node('leaf', 0, 280)],
    edges: [edge('a', 'z'), edge('obstacle', 'leaf')]};
  graph.nodes[0].pinned = graph.nodes[1].pinned = true;
  const result = await computeGraphLayout(graph, {refine: true});
  const placed = graph.nodes.map(n => ({...n, ...result.positions.get(n.id)}));
  assert.equal(layoutMetrics(graph, result.positions).edgeNodeOverlaps, 0, 'repair clears the center-line obstruction before routing');
  assert.equal(sampledObstructions(placed, graph.edges, result.bends), 0);
  for (const n of graph.nodes.filter(n => n.pinned)) assert.deepEqual(result.positions.get(n.id), {x: n.x, y: n.y});
  for (const n of graph.nodes) assert.ok(Math.hypot(result.positions.get(n.id).x - n.x, result.positions.get(n.id).y - n.y) <= 300);
});

test('readability cleanup preserves neighborhood bounds, roomier clearance and graph identity', () => {
  const graph = {revision: 1, nodes: Array.from({length: 32}, (_, i) => node(String(i), i % 8 * 260, Math.floor(i / 8) * 150)),
    edges: Array.from({length: 40}, (_, i) => edge(String(i % 32), String((i * 7 + 13) % 32), `e${i}`))};
  graph.nodes[0].pinned = true;
  const original = structuredClone(graph), positions = new Map(graph.nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  const before = layoutMetrics(graph, positions), all = graph.nodes.map((_, i) => i);
  const stats = improveLayoutReadability(graph, positions, {}, [all]);
  const after = layoutMetrics(graph, positions);
  assert.ok(stats.moves > 0);
  assert.ok(after.edgeNodeOverlaps <= before.edgeNodeOverlaps);
  assert.ok(after.edgeCrossings <= before.edgeCrossings);
  assert.ok(after.edgeNodeOverlaps < before.edgeNodeOverlaps || after.edgeCrossings < before.edgeCrossings);
  assert.equal(indexedIntersections(graph, positions), 0);
  assert.deepEqual(positions.get('0'), {x: 0, y: 0});
  const widths = graph.nodes.map(n => graphNodeSize(n).width);
  for (let i = 0; i < graph.nodes.length; i++) {
    const n = graph.nodes[i], p = positions.get(n.id), size = graphNodeSize(n);
    assert.ok(p.x - size.width / 2 >= -Math.max(...widths) / 2 - .01 && p.x + size.width / 2 <= 1820 + Math.max(...widths) / 2 + .01);
    assert.ok(p.y >= -.01 && p.y <= 450.01);
    for (let j = 0; j < i; j++) {
      const q = positions.get(graph.nodes[j].id), other = graphNodeSize(graph.nodes[j]);
      assert.ok(Math.abs(p.x - q.x) >= (size.width + other.width) / 2 + 48 - .01 ||
        Math.abs(p.y - q.y) >= (size.height + other.height) / 2 + 36 - .01);
    }
  }
  assert.deepEqual(graph, original);
});

test('local cleanup only moves the allowed set, and large maps skip detailed scoring', () => {
  const nodes = [node('a', -400, 0), node('z', 400, 0), node('blocker', 0, 0)];
  const graph = {revision: 1, nodes, edges: [edge('a', 'z')]};
  const positions = new Map(nodes.map(n => [n.id, {x: n.x, y: n.y}]));
  improveLayoutReadability(graph, positions, {incremental: true, movableNodeIds: new Set(['blocker'])});
  assert.deepEqual(positions.get('a'), {x: -400, y: 0});
  assert.deepEqual(positions.get('z'), {x: 400, y: 0});
  assert.equal(layoutMetrics(graph, positions).edgeNodeOverlaps, 0);
  const large = {revision: 1, nodes: Array.from({length: 1501}, (_, i) => node(String(i), i * 200, 0)), edges: []};
  assert.deepEqual(improveLayoutReadability(large, new Map()), {moves: 0, checks: 0, capped: false});
});

test('obstacle routing retains separate parallel lanes, reverse direction and self loops', () => {
  const nodes = [node('a', 0, 0), node('z', 0, 1000), node('blocker', 0, 500)];
  const edges = [edge('a', 'z', 'one'), edge('z', 'a', 'two'), edge('a', 'z', 'three'), edge('a', 'a', 'loop')];
  const bends = optimizeEdgeBends(nodes, edges, 1);
  assert.equal(bends.size, 4);
  assert.equal(new Set(edges.slice(0, 3).map(e => bends.get(e.id))).size, 3);
  assert.ok([...bends.values()].every(Number.isFinite));
  assert.equal(sampledObstructions(nodes, edges, bends), 0);
});

test('geometry-only repair does not drop obstacle routing above the old 500-edge cutoff', async () => {
  const nodes = [node('a', 0, 0), node('z', 0, 2000), node('blocker', 0, 1000)], edges = [edge('a', 'z')];
  for (let i = 0; i < 500; i++) {
    nodes.push(node(`s${i}`, 10000, i * 160), node(`t${i}`, 10400, i * 160));
    edges.push(edge(`s${i}`, `t${i}`));
  }
  const result = await computeGraphLayout({revision: 1, nodes, edges}, {repairOnly: true});
  assert.ok(Math.abs(result.bends.get('a-z')) > 100);
  assert.deepEqual(result.positions, new Map(nodes.map(n => [n.id, {x: n.x, y: n.y}])));
});
